#define _DARWIN_C_SOURCE 1
#include <signal.h>
#include <sys/time.h>
#include <string.h>
static volatile sig_atomic_t count = 0;
static void pulse(int value) { (void)value; count++; }
int начать_прерывания(void) { struct sigaction a; memset(&a, 0, sizeof(a)); a.sa_handler = pulse; sigemptyset(&a.sa_mask); if (sigaction(SIGALRM, &a, 0) != 0) return -1; struct itimerval t = {{0, 1000}, {0, 1000}}; count = 0; return setitimer(ITIMER_REAL, &t, 0); }
int остановить_прерывания(void) { struct itimerval t = {{0,0},{0,0}}; return setitimer(ITIMER_REAL, &t, 0); }
int число_прерываний(void) { return (int)count; }

