import Foundation
import Darwin
enum СбойПроцессаПробы: Error { case параметры, исход, группа }
@main enum ПробаПроцесса { static func main() throws { let a=Array(CommandLine.arguments.dropFirst()); guard a.count == 2 else { throw СбойПроцессаПробы.параметры }; for режим in ["normal","failure","overflow"] { let файл=a[1]+"/"+режим+".pgid"; let начало=DispatchTime.now().uptimeNanoseconds; var предел=false; do { let р=try ограниченныйПроцесс(a[0],[режим,файл],среда:["PATH":"/usr/bin:/bin"],предел:16); guard режим != "overflow", р.код == (режим == "normal" ? 0 : 7) else { throw СбойПроцессаПробы.исход } } catch let e as ОтказЦелостности { guard режим == "overflow", e.причина == "предел", e.выход == 2 else { throw e }; предел=true }; let конец=DispatchTime.now().uptimeNanoseconds; let текст=try String(contentsOfFile:файл,encoding:.utf8).trimmingCharacters(in:.whitespacesAndNewlines); guard let группа=Int32(текст), группа > 0 else { throw СбойПроцессаПробы.группа }; errno=0; let код=Darwin.kill(-группа,0); let ошибка=errno; guard код == -1 && ошибка == ESRCH, конец >= начало, конец-начало < 2_000_000_000 else { throw СбойПроцессаПробы.группа }; print("mode=\(режим) limit=\(предел) group_absent=1 elapsed_ns=\(конец-начало)") } } }
